    "{0}: replace its save with {1}? The current save is kept, renamed to {2}." to Tr(ja = "{0}: セーブを {1}に おきかえますか? いまの セーブは {2}という なまえで のこります。", fr = "{0} : remplacer sa sauvegarde par {1} ? L'actuelle est conservée sous le nom {2}.", de = "{0}: Speicherstand durch {1} ersetzen? Der aktuelle bleibt erhalten, umbenannt in {2}.", it = "{0}: sostituire il salvataggio con {1}? Quello attuale resta, rinominato {2}.", es = "{0}: ¿reemplazar su partida por {1}? La actual se conserva con el nombre {2}.", br = "{0}: substituir o save por {1}? O save atual é mantido, renomeado para {2}.", pt = "{0}: substituir a gravação por {1}? A atual é mantida, com o nome {2}.", zh = "{0}：用{1}替换存档吗？当前存档会保留并重命名为{2}。"),
