    "Sign in (Settings > RetroAchievements) to see yours" to Tr(ja = "ログインすると じぶんの きろくが みられます (せってい > RetroAchievements)", fr = "Connectez-vous (Options > RetroAchievements) pour voir les vôtres", de = "Melde dich an (Optionen > RetroAchievements), um deine zu sehen", it = "Accedi (Opzioni > RetroAchievements) per vedere i tuoi", es = "Inicia sesión (Ajustes > RetroAchievements) para ver los tuyos", br = "Entre (Configurações > RetroAchievements) para ver as suas", pt = "Inicie sessão (Definições > RetroAchievements) para ver as suas", zh = "登录后可查看你的记录（设置 > RetroAchievements）"),
