    "Allow PokéDaisy to install apps, then come back" to Tr(ja = "PokéDaisyに アプリの インストールを きょかして もどってください", fr = "Autorisez PokéDaisy à installer des applis, puis revenez", de = "Erlaube PokéDaisy, Apps zu installieren, und komm zurück", it = "Consenti a PokéDaisy di installare app, poi torna qui", es = "Permite que PokéDaisy instale apps y vuelve", br = "Permita que o PokéDaisy instale apps e volte", pt = "Permita que o PokéDaisy instale aplicações e volte", zh = "允许 PokéDaisy 安装应用后返回"),
    "ANDROID'S INSTALLER DIDN'T OPEN - GET THE APK FROM THE RELEASE PAGE" to Tr(ja = "Androidの インストーラーが ひらきません - リリースページから APKを いれてください", fr = "L'INSTALLATEUR D'ANDROID NE S'EST PAS OUVERT - PRENEZ L'APK SUR LA PAGE DE VERSION", de = "ANDROIDS INSTALLER GING NICHT AUF - HOL DIE APK VON DER RELEASE-SEITE", it = "IL PROGRAMMA DI INSTALLAZIONE NON SI È APERTO - SCARICA L'APK DALLA PAGINA DELLA VERSIONE", es = "EL INSTALADOR DE ANDROID NO SE ABRIÓ - DESCARGA EL APK DE LA PÁGINA DE LA VERSIÓN", br = "O INSTALADOR DO ANDROID NÃO ABRIU - BAIXE O APK NA PÁGINA DA VERSÃO", pt = "O INSTALADOR DO ANDROID NÃO ABRIU - TRANSFIRA O APK NA PÁGINA DA VERSÃO", zh = "无法打开 ANDROID 安装程序，请从发布页面获取 APK"),
