    "Rewind is off - turn it on in SETTINGS" to Tr(ja = "まきもどしは オフです - せっていで オンに", fr = "Retour arrière désactivé - activez-le dans OPTIONS", de = "Zurückspulen ist aus - in OPTIONEN einschalten", it = "Riavvolgimento disattivato - attivalo in OPZIONI", es = "Rebobinar está desactivado - actívalo en AJUSTES", br = "Rebobinar está desativado - ative em CONFIG.", pt = "Rebobinar está desativado - ative-o em DEFINIÇÕES", zh = "倒退已关闭，请在设置中开启"),
