    "Normal speed" to Tr(ja = "ふつうの はやさ", fr = "Vitesse normale", de = "Normale Geschwindigkeit", it = "Velocità normale", es = "Velocidad normal", br = "Velocidade normal", pt = "Velocidade normal", zh = "正常速度"),
    "Speed {0}×" to Tr(ja = "はやさ {0}×", fr = "Vitesse {0}×", de = "Tempo {0}×", it = "Velocità {0}×", es = "Velocidad {0}×", br = "Velocidade {0}×", pt = "Velocidade {0}×", zh = "速度 {0}×"),
    "Your save changed since you last played here, so the game started from the save file" to Tr(ja = "まえに ここで あそんだあと セーブが かわったので セーブファイルから はじめました", fr = "Ta sauvegarde a changé depuis ta dernière partie ici : le jeu a démarré depuis le fichier de sauvegarde", de = "Dein Spielstand hat sich seit dem letzten Spiel hier geändert, daher startete das Spiel aus der Speicherdatei", it = "Il salvataggio è cambiato dall'ultima partita qui, quindi il gioco è partito dal file di salvataggio", es = "Tu partida cambió desde la última vez que jugaste aquí, así que el juego empezó desde el archivo de guardado", br = "Seu save mudou desde a última vez que você jogou aqui, então o jogo começou pelo arquivo de save", pt = "A gravação mudou desde a última vez que jogou aqui, por isso o jogo começou pelo ficheiro de gravação", zh = "自上次游玩后存档已改变，因此游戏从存档文件启动"),
    // ScreenScraper: sign-in, the update's popup, setup's GAME MEDIA step, Settings > ScreenScraper
    "ScreenScraper stopped: {0}" to Tr(ja = "ScreenScraperが とまりました: {0}", fr = "ScreenScraper arrêté : {0}", de = "ScreenScraper gestoppt: {0}", it = "ScreenScraper fermato: {0}", es = "ScreenScraper se detuvo: {0}", br = "O ScreenScraper parou: {0}", pt = "O ScreenScraper parou: {0}", zh = "ScreenScraper 已停止：{0}"),
    "No account in the answer" to Tr(ja = "こたえに アカウントが ありません", fr = "Aucun compte dans la réponse", de = "Kein Konto in der Antwort", it = "Nessun account nella risposta", es = "No hay cuenta en la respuesta", br = "Nenhuma conta na resposta", pt = "Nenhuma conta na resposta", zh = "返回结果中没有账户"),
    "This build has no ScreenScraper developer access" to Tr(ja = "この ビルドは ScreenScraperの かいはつしゃ アクセスが ありません", fr = "Cette version n'a pas d'accès développeur ScreenScraper", de = "Diese Version hat keinen ScreenScraper-Entwicklerzugang", it = "Questa versione non ha l'accesso sviluppatore ScreenScraper", es = "Esta versión no tiene acceso de desarrollador a ScreenScraper", br = "Esta versão não tem acesso de desenvolvedor ao ScreenScraper", pt = "Esta versão não tem acesso de programador ao ScreenScraper", zh = "此版本没有 ScreenScraper 开发者访问权限"),
