    "Game not found" to Tr(ja = "ゲームが みつかりません", fr = "Jeu introuvable", de = "Spiel nicht gefunden", it = "Gioco non trovato", es = "Juego no encontrado", br = "Jogo não encontrado", pt = "Jogo não encontrado", zh = "未找到游戏"),
    "ScreenScraper's API is closed for now" to Tr(ja = "ScreenScraperの APIは いま とじています", fr = "L'API de ScreenScraper est fermée pour l'instant", de = "Die ScreenScraper-API ist gerade geschlossen", it = "L'API di ScreenScraper è chiusa per ora", es = "La API de ScreenScraper está cerrada por ahora", br = "A API do ScreenScraper está fechada por enquanto", pt = "A API do ScreenScraper está fechada por agora", zh = "ScreenScraper API 暂时关闭"),
    "ScreenScraper doesn't accept this app version" to Tr(ja = "ScreenScraperが この バージョンを うけつけません", fr = "ScreenScraper refuse cette version de l'app", de = "ScreenScraper akzeptiert diese App-Version nicht", it = "ScreenScraper non accetta questa versione dell'app", es = "ScreenScraper no acepta esta versión de la app", br = "O ScreenScraper não aceita esta versão do app", pt = "O ScreenScraper não aceita esta versão da app", zh = "ScreenScraper 不接受此应用版本"),
    "Too many requests at once" to Tr(ja = "いちどに リクエストが おおすぎます", fr = "Trop de requêtes à la fois", de = "Zu viele Anfragen auf einmal", it = "Troppe richieste insieme", es = "Demasiadas solicitudes a la vez", br = "Muitas solicitações ao mesmo tempo", pt = "Demasiados pedidos ao mesmo tempo", zh = "同时发出的请求过多"),
    "Today's ScreenScraper quota is used up" to Tr(ja = "きょうの ScreenScraperの りょうを つかいきりました", fr = "Le quota ScreenScraper du jour est épuisé", de = "Das heutige ScreenScraper-Kontingent ist aufgebraucht", it = "La quota ScreenScraper di oggi è esaurita", es = "Se agotó la cuota de ScreenScraper de hoy", br = "A cota de hoje do ScreenScraper acabou", pt = "A quota de hoje do ScreenScraper esgotou-se", zh = "今日 ScreenScraper 配额已用完"),
    "Too many unknown ROMs today" to Tr(ja = "きょうは しらない ROMが おおすぎます", fr = "Trop de ROM inconnues aujourd'hui", de = "Heute zu viele unbekannte ROMs", it = "Troppe ROM sconosciute oggi", es = "Demasiadas ROM desconocidas hoy", br = "Muitas ROMs desconhecidas hoje", pt = "Demasiadas ROMs desconhecidas hoje", zh = "今日未知 ROM 过多"),
    "Can't reach ScreenScraper - check the connection" to Tr(ja = "ScreenScraperに つながりません - せつぞくを たしかめてください", fr = "Impossible de joindre ScreenScraper - vérifiez la connexion", de = "ScreenScraper nicht erreichbar - prüf die Verbindung", it = "Impossibile raggiungere ScreenScraper - controlla la connessione", es = "No se puede conectar con ScreenScraper - revisa la conexión", br = "Não foi possível acessar o ScreenScraper - verifique a conexão", pt = "Não foi possível aceder ao ScreenScraper - verifique a ligação", zh = "无法连接 ScreenScraper，请检查网络连接"),
    "{0} OF {1} REQUESTS USED TODAY" to Tr(ja = "きょう {1}かいのうち {0}かい つかいました", fr = "{0} SUR {1} REQUÊTES UTILISÉES AUJOURD'HUI", de = "{0} VON {1} ANFRAGEN HEUTE GENUTZT", it = "{0} DI {1} RICHIESTE USATE OGGI", es = "{0} DE {1} SOLICITUDES USADAS HOY", br = "{0} DE {1} SOLICITAÇÕES USADAS HOJE", pt = "{0} DE {1} PEDIDOS USADOS HOJE", zh = "今日已使用 {0} / {1} 次请求"),
    "screenscraper.fr username" to Tr(ja = "screenscraper.frの ユーザーめい", fr = "identifiant screenscraper.fr", de = "screenscraper.fr-Benutzername", it = "nome utente screenscraper.fr", es = "usuario de screenscraper.fr", br = "usuário do screenscraper.fr", pt = "utilizador do screenscraper.fr", zh = "screenscraper.fr 用户名"),
    "NO ACCOUNT? SIGN UP" to Tr(ja = "アカウントを つくる", fr = "PAS DE COMPTE ? S'INSCRIRE", de = "KEIN KONTO? REGISTRIEREN", it = "NESSUN ACCOUNT? REGISTRATI", es = "¿SIN CUENTA? REGÍSTRATE", br = "SEM CONTA? CADASTRE-SE", pt = "SEM CONTA? REGISTE-SE", zh = "没有账户？注册"),
    "NEW: GAME MEDIA FROM SCREENSCRAPER" to Tr(ja = "あたらしい: ScreenScraperの ゲームメディア", fr = "NOUVEAU : MÉDIAS DE JEU SCREENSCRAPER", de = "NEU: SPIELMEDIEN VON SCREENSCRAPER", it = "NOVITÀ: MEDIA DI GIOCO DA SCREENSCRAPER", es = "NUEVO: MEDIOS DE JUEGO DE SCREENSCRAPER", br = "NOVO: MÍDIA DE JOGOS DO SCREENSCRAPER", pt = "NOVO: MULTIMÉDIA DE JOGOS DO SCREENSCRAPER", zh = "新功能：来自 SCREENSCRAPER 的游戏媒体"),
    "Box art, screenshots, title screens, logos, videos and each game's story for your whole library, from ScreenScraper.fr. It comes first for covers, and with two screens the library shows the game you're on, in full, on the other one." to Tr(ja = "ScreenScraper.frから ライブラリ ぜんぶの パッケージ、 スクリーンショット、 タイトルがめん、 ロゴ、 どうが、 ゲームの あらすじを とってきます。 カバーには これが いちばんに つかわれ、 がめんが ふたつ あれば えらんだ ゲームの すべてを もう ひとつの がめんに だします。", fr = "Jaquettes, captures, écrans titre, logos, vidéos et le résumé de chaque jeu pour toute votre bibliothèque, depuis ScreenScraper.fr. Il passe en premier pour les jaquettes et, avec deux écrans, la bibliothèque affiche le jeu sélectionné en entier sur l'autre.", de = "Cover, Screenshots, Titelbildschirme, Logos, Videos und die Story jedes Spiels für deine ganze Bibliothek, von ScreenScraper.fr. Es kommt bei Covern zuerst, und mit zwei Bildschirmen zeigt die Bibliothek das gewählte Spiel ganz auf dem anderen.", it = "Copertine, screenshot, schermate del titolo, loghi, video e la trama di ogni gioco per tutta la libreria, da ScreenScraper.fr. Ha la precedenza per le copertine e, con due schermi, la libreria mostra il gioco selezionato per intero sull'altro.", es = "Portadas, capturas, pantallas de título, logotipos, vídeos y la historia de cada juego para toda tu biblioteca, de ScreenScraper.fr. Tiene prioridad para las portadas y, con dos pantallas, la biblioteca muestra el juego elegido entero en la otra.", br = "Capas, capturas de tela, telas de título, logotipos, vídeos e a história de cada jogo para toda a sua biblioteca, do ScreenScraper.fr. Tem prioridade nas capas e, com duas telas, a biblioteca mostra o jogo selecionado, completo, na outra.", pt = "Capas, capturas de ecrã, ecrãs de título, logótipos, vídeos e a história de cada jogo para toda a sua biblioteca, do ScreenScraper.fr. Tem prioridade nas capas e, com dois ecrãs, a biblioteca mostra o jogo selecionado, completo, no outro.", zh = "从 ScreenScraper.fr 为整个游戏库获取封面、截图、标题画面、标志、视频和游戏介绍。封面优先使用此来源；在双屏设备上，游戏库会在另一屏显示所选游戏的完整资料。"),
    "It needs a free screenscraper.fr account. Set it up now?" to Tr(ja = "むりょうの screenscraper.frの アカウントが いります。 いま せっていしますか?", fr = "Il faut un compte screenscraper.fr gratuit. Le configurer maintenant ?", de = "Dafür brauchst du ein kostenloses screenscraper.fr-Konto. Jetzt einrichten?", it = "Serve un account gratuito screenscraper.fr. Configurarlo ora?", es = "Necesita una cuenta gratuita de screenscraper.fr. ¿Configurarla ahora?", br = "Precisa de uma conta gratuita do screenscraper.fr. Configurar agora?", pt = "Precisa de uma conta gratuita do screenscraper.fr. Configurar agora?", zh = "需要免费的 screenscraper.fr 账户，现在设置吗？"),
    "SIGNED IN AS {0}" to Tr(ja = "{0}で ログインちゅう", fr = "CONNECTÉ EN TANT QUE {0}", de = "ANGEMELDET ALS {0}", it = "ACCESSO COME {0}", es = "SESIÓN INICIADA COMO {0}", br = "CONECTADO COMO {0}", pt = "SESSÃO INICIADA COMO {0}", zh = "已登录为 {0}"),
    "GAME MEDIA (OPTIONAL)" to Tr(ja = "ゲームメディア (にんい)", fr = "MÉDIAS DE JEU (FACULTATIF)", de = "SPIELMEDIEN (OPTIONAL)", it = "MEDIA DI GIOCO (FACOLTATIVO)", es = "MEDIOS DE JUEGO (OPCIONAL)", br = "MÍDIA DE JOGOS (OPCIONAL)", pt = "MULTIMÉDIA DE JOGOS (OPCIONAL)", zh = "游戏媒体（可选）"),
    "ScreenScraper.fr has box art, screenshots, title screens, logos, videos and each game's story. Sign in with your free account and PokéDaisy fetches them for every game: covers in the library, and with two screens, everything about the game you're on on the other screen." to Tr(ja = "ScreenScraper.frには パッケージ、 スクリーンショット、 タイトルがめん、 ロゴ、 どうが、 ゲームの あらすじが あります。 むりょうの アカウントで ログインすると PokéDaisyが すべての ゲームの ぶんを とってきます: ライブラリの カバーと、 がめんが ふたつ あれば えらんだ ゲームの すべてを もう ひとつの がめんに。", fr = "ScreenScraper.fr a les jaquettes, captures, écrans titre, logos, vidéos et le résumé de chaque jeu. Connectez-vous avec votre compte gratuit et PokéDaisy les récupère pour chaque jeu : jaquettes dans la bibliothèque et, avec deux écrans, tout sur le jeu sélectionné sur l'autre écran.", de = "ScreenScraper.fr hat Cover, Screenshots, Titelbildschirme, Logos, Videos und die Story jedes Spiels. Melde dich mit deinem kostenlosen Konto an und PokéDaisy holt sie für jedes Spiel: Cover in der Bibliothek und, mit zwei Bildschirmen, alles über das gewählte Spiel auf dem anderen.", it = "ScreenScraper.fr ha copertine, screenshot, schermate del titolo, loghi, video e la trama di ogni gioco. Accedi con il tuo account gratuito e PokéDaisy li scarica per ogni gioco: copertine nella libreria e, con due schermi, tutto sul gioco selezionato sull'altro schermo.", es = "ScreenScraper.fr tiene portadas, capturas, pantallas de título, logotipos, vídeos y la historia de cada juego. Inicia sesión con tu cuenta gratuita y PokéDaisy los descarga para cada juego: portadas en la biblioteca y, con dos pantallas, todo sobre el juego elegido en la otra.", br = "O ScreenScraper.fr tem capas, capturas de tela, telas de título, logotipos, vídeos e a história de cada jogo. Entre com sua conta gratuita e o PokéDaisy baixa tudo para cada jogo: capas na biblioteca e, com duas telas, tudo sobre o jogo selecionado na outra tela.", pt = "O ScreenScraper.fr tem capas, capturas de ecrã, ecrãs de título, logótipos, vídeos e a história de cada jogo. Inicie sessão com a sua conta gratuita e o PokéDaisy transfere tudo para cada jogo: capas na biblioteca e, com dois ecrãs, tudo sobre o jogo selecionado no outro ecrã.", zh = "ScreenScraper.fr 提供封面、截图、标题画面、标志、视频和游戏介绍。使用免费账户登录后，PokéDaisy 会为每款游戏获取资料：游戏库显示封面，双屏设备的另一屏显示当前游戏的完整资料。"),
    "Skip this if you like - sign in any time in SETTINGS > SCREENSCRAPER." to Tr(ja = "スキップしても だいじょうぶ - いつでも せってい > SCREENSCRAPER で ログインできます。", fr = "Passez si vous voulez - connectez-vous quand vous voulez dans OPTIONS > SCREENSCRAPER.", de = "Überspring das ruhig - anmelden geht jederzeit unter OPTIONEN > SCREENSCRAPER.", it = "Puoi saltarlo - accedi quando vuoi in OPZIONI > SCREENSCRAPER.", es = "Puedes omitirlo - inicia sesión cuando quieras en AJUSTES > SCREENSCRAPER.", br = "Pule isto se quiser - entre quando quiser em CONFIGURAÇÕES > SCREENSCRAPER.", pt = "Salte isto se quiser - inicie sessão quando quiser em DEFINIÇÕES > SCREENSCRAPER.", zh = "也可以跳过，之后随时在设置 > SCREENSCRAPER 中登录。"),
    "ScreenScraper.fr has box art, screenshots, title screens, logos, videos and each game's story. With your free account, PokéDaisy fetches them once per game and keeps them on the device. Its box art comes first for library covers, and with two screens the launcher shows the game you're on, in full, on the other one." to Tr(ja = "ScreenScraper.frには パッケージ、 スクリーンショット、 タイトルがめん、 ロゴ、 どうが、 ゲームの あらすじが あります。 むりょうの アカウントで PokéDaisyが ゲームごとに いちど とってきて きかいに のこします。 ライブラリの カバーには その パッケージが いちばんに つかわれ、 がめんが ふたつ あれば ランチャーが えらんだ ゲームの すべてを もう ひとつの がめんに だします。", fr = "ScreenScraper.fr a les jaquettes, captures, écrans titre, logos, vidéos et le résumé de chaque jeu. Avec votre compte gratuit, PokéDaisy les récupère une fois par jeu et les garde sur l'appareil. Ses jaquettes passent en premier dans la bibliothèque et, avec deux écrans, le lanceur affiche le jeu sélectionné en entier sur l'autre.", de = "ScreenScraper.fr hat Cover, Screenshots, Titelbildschirme, Logos, Videos und die Story jedes Spiels. Mit deinem kostenlosen Konto holt PokéDaisy sie einmal pro Spiel und behält sie auf dem Gerät. Seine Cover kommen in der Bibliothek zuerst, und mit zwei Bildschirmen zeigt der Launcher das gewählte Spiel ganz auf dem anderen.", it = "ScreenScraper.fr ha copertine, screenshot, schermate del titolo, loghi, video e la trama di ogni gioco. Con il tuo account gratuito, PokéDaisy li scarica una volta per gioco e li tiene sul dispositivo. Le sue copertine hanno la precedenza nella libreria e, con due schermi, il launcher mostra il gioco selezionato per intero sull'altro.", es = "ScreenScraper.fr tiene portadas, capturas, pantallas de título, logotipos, vídeos y la historia de cada juego. Con tu cuenta gratuita, PokéDaisy los descarga una vez por juego y los guarda en el dispositivo. Sus portadas tienen prioridad en la biblioteca y, con dos pantallas, el lanzador muestra el juego elegido entero en la otra.", br = "O ScreenScraper.fr tem capas, capturas de tela, telas de título, logotipos, vídeos e a história de cada jogo. Com sua conta gratuita, o PokéDaisy baixa tudo uma vez por jogo e guarda no aparelho. As capas dele têm prioridade na biblioteca e, com duas telas, o launcher mostra o jogo selecionado, completo, na outra.", pt = "O ScreenScraper.fr tem capas, capturas de ecrã, ecrãs de título, logótipos, vídeos e a história de cada jogo. Com a sua conta gratuita, o PokéDaisy transfere tudo uma vez por jogo e guarda-o no dispositivo. As capas dele têm prioridade na biblioteca e, com dois ecrãs, o launcher mostra o jogo selecionado, completo, no outro.", zh = "ScreenScraper.fr 提供封面、截图、标题画面、标志、视频和游戏介绍。使用免费账户后，PokéDaisy 会为每款游戏获取一次并保存在设备上。游戏库优先使用此来源的封面；双屏设备的另一屏显示所选游戏的完整资料。"),
    "DOWNLOAD VIDEOS" to Tr(ja = "どうがも ダウンロード", fr = "TÉLÉCHARGER LES VIDÉOS", de = "VIDEOS LADEN", it = "SCARICA VIDEO", es = "DESCARGAR VÍDEOS", br = "BAIXAR VÍDEOS", pt = "TRANSFERIR VÍDEOS", zh = "下载视频"),
    "FETCH MEDIA NOW" to Tr(ja = "いま メディアを とる", fr = "RÉCUPÉRER MAINTENANT", de = "MEDIEN JETZT LADEN", it = "SCARICA MEDIA ORA", es = "DESCARGAR MEDIOS YA", br = "BAIXAR MÍDIA AGORA", pt = "OBTER MULTIMÉDIA JÁ", zh = "立即获取媒体"),
