    "DEVELOPER" to Tr(ja = "かいはつ", fr = "DÉVELOPPEUR", de = "ENTWICKLER", it = "SVILUPPATORE", es = "DESARROLLADOR", br = "DESENVOLVEDOR", pt = "PROGRAMADOR", zh = "开发商"),
    "PUBLISHER" to Tr(ja = "はんばい", fr = "ÉDITEUR", de = "PUBLISHER", it = "EDITORE", es = "EDITOR", br = "DISTRIBUIDORA", pt = "EDITORA", zh = "发行商"),
    "GENRE" to Tr(ja = "ジャンル", fr = "GENRE", de = "GENRE", it = "GENERE", es = "GÉNERO", br = "GÊNERO", pt = "GÉNERO", zh = "类型"),
    "PLAYERS" to Tr(ja = "にんずう", fr = "JOUEURS", de = "SPIELER", it = "GIOCATORI", es = "JUGADORES", br = "JOGADORES", pt = "JOGADORES", zh = "玩家人数"),
    "RATING" to Tr(ja = "ひょうか", fr = "NOTE", de = "WERTUNG", it = "VOTO", es = "NOTA", br = "NOTA", pt = "NOTA", zh = "评分"),
    "Sign in to ScreenScraper in SETTINGS for this game's box art, screenshots, video and story." to Tr(ja = "せってい で ScreenScraperに ログインすると この ゲームの パッケージ、 スクリーンショット、 どうが、 あらすじが でます。", fr = "Connectez-vous à ScreenScraper dans OPTIONS pour la jaquette, les captures, la vidéo et le résumé de ce jeu.", de = "Melde dich in OPTIONEN bei ScreenScraper an für Cover, Screenshots, Video und Story dieses Spiels.", it = "Accedi a ScreenScraper in OPZIONI per copertina, screenshot, video e trama di questo gioco.", es = "Inicia sesión en ScreenScraper en AJUSTES para la portada, capturas, vídeo e historia de este juego.", br = "Entre no ScreenScraper em CONFIG. para ver a capa, capturas, vídeo e história deste jogo.", pt = "Inicie sessão no ScreenScraper em DEFINIÇÕES para ver a capa, capturas, vídeo e história deste jogo.", zh = "在设置中登录 ScreenScraper 后可获取此游戏的封面、截图、视频和介绍。"),
    "ScreenScraper has nothing for this game yet." to Tr(ja = "ScreenScraperには この ゲームの ものが まだ ありません。", fr = "ScreenScraper n'a encore rien pour ce jeu.", de = "ScreenScraper hat für dieses Spiel noch nichts.", it = "ScreenScraper non ha ancora nulla per questo gioco.", es = "ScreenScraper aún no tiene nada de este juego.", br = "O ScreenScraper ainda não tem nada deste jogo.", pt = "O ScreenScraper ainda não tem nada deste jogo.", zh = "ScreenScraper 暂无此游戏的资料。"),
    "From ScreenScraper" to Tr(ja = "ScreenScraperから", fr = "De ScreenScraper", de = "Von ScreenScraper", it = "Da ScreenScraper", es = "De ScreenScraper", br = "Do ScreenScraper", pt = "Do ScreenScraper", zh = "来自 ScreenScraper"),
    "Show password" to Tr(ja = "パスワードを みせる", fr = "Afficher le mot de passe", de = "Passwort zeigen", it = "Mostra password", es = "Mostrar contraseña", br = "Mostrar senha", pt = "Mostrar palavra-passe", zh = "显示密码"),
    "Hide password" to Tr(ja = "パスワードを かくす", fr = "Masquer le mot de passe", de = "Passwort verbergen", it = "Nascondi password", es = "Ocultar contraseña", br = "Ocultar senha", pt = "Ocultar palavra-passe", zh = "隐藏密码"),
    "ScreenScraper says: {0}" to Tr(ja = "ScreenScraperの こたえ: {0}", fr = "ScreenScraper répond : {0}", de = "ScreenScraper sagt: {0}", it = "ScreenScraper risponde: {0}", es = "ScreenScraper dice: {0}", br = "O ScreenScraper diz: {0}", pt = "O ScreenScraper diz: {0}", zh = "ScreenScraper 返回：{0}"),
    "ScreenScraper sent an answer the app can't read" to Tr(ja = "ScreenScraperの こたえが よめません", fr = "ScreenScraper a envoyé une réponse illisible", de = "ScreenScraper schickte eine unlesbare Antwort", it = "ScreenScraper ha inviato una risposta illeggibile", es = "ScreenScraper envió una respuesta ilegible", br = "O ScreenScraper enviou uma resposta que o app não consegue ler", pt = "O ScreenScraper enviou uma resposta que a app não consegue ler", zh = "ScreenScraper 返回了应用无法读取的结果"),
    "This build has no ScreenScraper developer login, so ScreenScraper may refuse to sign in. Release builds have one." to Tr(ja = "この ビルドには ScreenScraperの かいはつしゃ ログインが ないので ログインを ことわられることが あります。 リリース ビルドには あります。", fr = "Cette version n'a pas d'identifiant développeur ScreenScraper : la connexion peut être refusée. Les versions publiées en ont un.", de = "Diese Version hat keinen ScreenScraper-Entwicklerzugang, die Anmeldung kann abgelehnt werden. Veröffentlichte Versionen haben einen.", it = "Questa versione non ha l'accesso sviluppatore ScreenScraper, quindi l'accesso può essere rifiutato. Le versioni pubblicate ce l'hanno.", es = "Esta versión no tiene acceso de desarrollador a ScreenScraper, así que puede rechazar el inicio de sesión. Las versiones publicadas lo tienen.", br = "Esta versão não tem login de desenvolvedor do ScreenScraper, então ele pode recusar a entrada. As versões publicadas têm.", pt = "Esta versão não tem credenciais de programador do ScreenScraper, por isso pode recusar o início de sessão. As versões publicadas têm.", zh = "此构建没有 ScreenScraper 开发者登录信息，因此 ScreenScraper 可能拒绝登录。发布版本包含该信息。"),
    // PC BOXES (a game's save, read and rearranged from the library)
    "PC BOXES" to Tr(ja = "パソコンの ボックス", fr = "BOÎTES PC", de = "PC-BOXEN", it = "BOX PC", es = "CAJAS PC", br = "CAIXAS DO PC", pt = "CAIXAS DO PC", zh = "电脑盒子"),
    "PC BOXES reads FireRed, LeafGreen, Emerald, Ruby and Sapphire saves (and builds that keep their save layout). This game's isn't one yet." to Tr(ja = "パソコンの ボックスは ファイアレッド・リーフグリーン・エメラルド・ルビー・サファイアの セーブ (と おなじ かたちの セーブ)を よみます。 この ゲームの セーブには まだ たいおう していません。", fr = "BOÎTES PC lit les sauvegardes de Rouge Feu, Vert Feuille, Émeraude, Rubis et Saphir (et des versions au même format). Pas encore celle de ce jeu.", de = "PC-BOXEN liest Spielstände von Feuerrot, Blattgrün, Smaragd, Rubin und Saphir (und Versionen mit demselben Format). Den dieses Spiels noch nicht.", it = "BOX PC legge i salvataggi di Rosso Fuoco, Verde Foglia, Smeraldo, Rubino e Zaffiro (e versioni con lo stesso formato). Non ancora quello di questo gioco.", es = "CAJAS PC lee partidas de Rojo Fuego, Verde Hoja, Esmeralda, Rubí y Zafiro (y versiones con el mismo formato). Aún no la de este juego.", br = "CAIXAS DO PC lê saves de FireRed, LeafGreen, Emerald, Ruby e Sapphire (e versões com o mesmo formato de save). O deste jogo ainda não.", pt = "CAIXAS DO PC lê gravações de FireRed, LeafGreen, Emerald, Ruby e Sapphire (e versões com o mesmo formato). A deste jogo ainda não.", zh = "电脑盒子可读取火红、叶绿、绿宝石、红宝石和蓝宝石的存档，以及保留相同存档布局的版本。此游戏目前不在其中。"),
    "No save yet - save once in the game first." to Tr(ja = "セーブが まだ ありません。 さきに ゲームで いちど セーブしてください。", fr = "Pas encore de sauvegarde : sauvegardez d'abord une fois dans le jeu.", de = "Noch kein Spielstand - speichere zuerst einmal im Spiel.", it = "Nessun salvataggio: salva prima una volta nel gioco.", es = "Aún no hay partida: guarda una vez en el juego primero.", br = "Ainda não há save - salve uma vez no jogo primeiro.", pt = "Ainda não há gravação - guarde uma vez no jogo primeiro.", zh = "暂无存档，请先在游戏中保存一次。"),
    "Can't read the save {0}" to Tr(ja = "セーブ {0} を よめません", fr = "Impossible de lire la sauvegarde {0}", de = "Spielstand {0} kann nicht gelesen werden", it = "Impossibile leggere il salvataggio {0}", es = "No se puede leer la partida {0}", br = "Não é possível ler o save {0}", pt = "Não é possível ler a gravação {0}", zh = "无法读取存档{0}"),
    "This save doesn't look like a {0} save ({1}), so it's left alone." to Tr(ja = "この セーブは {0}の セーブに みえません ({1})。 そのままに します。", fr = "Cette sauvegarde ne ressemble pas à une sauvegarde {0} ({1}) : elle n'est pas touchée.", de = "Dieser Spielstand sieht nicht nach {0} aus ({1}), er bleibt unberührt.", it = "Questo salvataggio non sembra di {0} ({1}): resta com'è.", es = "Esta partida no parece de {0} ({1}): no se toca.", br = "Este save não parece de {0} ({1}), então não será alterado.", pt = "Esta gravação não parece de {0} ({1}), por isso não é alterada.", zh = "此文件不像是{0}的存档（{1}），因此未对其进行修改。"),
    "Saved. The previous save is in {0}" to Tr(ja = "セーブしました。 まえの セーブは {0} に あります", fr = "Sauvegardé. L'ancienne sauvegarde est dans {0}", de = "Gespeichert. Der vorige Spielstand liegt in {0}", it = "Salvato. Il salvataggio precedente è in {0}", es = "Guardado. La partida anterior está en {0}", br = "Salvo. O save anterior está em {0}", pt = "Guardado. A gravação anterior está em {0}", zh = "已保存，之前的存档位于{0}"),
    "Reading the save…" to Tr(ja = "セーブを よんでいます…", fr = "Lecture de la sauvegarde…", de = "Spielstand wird gelesen…", it = "Lettura del salvataggio…", es = "Leyendo la partida…", br = "Lendo o save…", pt = "A ler a gravação…", zh = "正在读取存档…"),
    "The save changed since it was opened - open it again" to Tr(ja = "ひらいてから セーブが かわりました。 もういちど ひらいてください", fr = "La sauvegarde a changé depuis son ouverture : rouvrez-la", de = "Der Spielstand hat sich seit dem Öffnen geändert - öffne ihn erneut", it = "Il salvataggio è cambiato dopo l'apertura: riaprilo", es = "La partida cambió desde que se abrió: ábrela de nuevo", br = "O save mudou desde que foi aberto - abra de novo", pt = "A gravação mudou desde que foi aberta - abra-a de novo", zh = "存档打开后已发生变化，请重新打开"),
    "Can't back up the save in {0} - nothing was changed" to Tr(ja = "{0} に セーブの バックアップを つくれません。 なにも かえていません", fr = "Impossible de copier la sauvegarde dans {0} : rien n'a été modifié", de = "Kein Backup in {0} möglich - nichts wurde geändert", it = "Impossibile fare il backup in {0}: nulla è stato cambiato", es = "No se puede copiar la partida en {0}: no se cambió nada", br = "Não é possível fazer backup do save em {0} - nada foi alterado", pt = "Não é possível fazer cópia de segurança da gravação em {0} - nada foi alterado", zh = "无法在{0}备份存档，未进行任何更改"),
    "The save didn't read back as written - the backup was put back" to Tr(ja = "かきこんだ セーブが ただしく よめません。 バックアップを もどしました", fr = "La sauvegarde ne se relit pas comme écrite : la copie a été remise", de = "Der Spielstand ließ sich nicht wie geschrieben lesen - das Backup wurde zurückgelegt", it = "Il salvataggio non si rilegge come scritto: il backup è stato rimesso", es = "La partida no se lee como se escribió: se repuso la copia", br = "O save não foi lido como foi gravado - o backup foi restaurado", pt = "A gravação não foi lida como foi escrita - a cópia de segurança foi reposta", zh = "写入后读回的存档不一致，已恢复备份"),
    "Too small for a Gen 3 save ({0} bytes)" to Tr(ja = "だい3せだいの セーブには ちいさすぎます ({0} バイト)", fr = "Trop petit pour une sauvegarde de 3e génération ({0} octets)", de = "Zu klein für einen Spielstand der 3. Generation ({0} Bytes)", it = "Troppo piccolo per un salvataggio di 3ª generazione ({0} byte)", es = "Demasiado pequeño para una partida de 3.ª generación ({0} bytes)", br = "Pequeno demais para um save da Geração 3 ({0} bytes)", pt = "Pequeno demais para uma gravação da Geração 3 ({0} bytes)", zh = "文件太小，不是第三世代存档（{0} 字节）"),
    "The save is empty - save once in the game first" to Tr(ja = "セーブが からです。 さきに ゲームで いちど セーブしてください", fr = "La sauvegarde est vide : sauvegardez d'abord une fois dans le jeu", de = "Der Spielstand ist leer - speichere zuerst einmal im Spiel", it = "Il salvataggio è vuoto: salva prima una volta nel gioco", es = "La partida está vacía: guarda una vez en el juego primero", br = "O save está vazio - salve uma vez no jogo primeiro", pt = "A gravação está vazia - guarde uma vez no jogo primeiro", zh = "存档为空，请先在游戏中保存一次"),
    "Neither save slot is intact - the game would call this save corrupted" to Tr(ja = "どちらの セーブも こわれています。 ゲームでも よめない セーブです", fr = "Aucun des deux emplacements n'est intact : le jeu la dirait corrompue", de = "Keiner der beiden Speicherplätze ist intakt - das Spiel hielte ihn für beschädigt", it = "Nessuno dei due slot è integro: il gioco lo direbbe danneggiato", es = "Ninguna de las dos ranuras está intacta: el juego la daría por dañada", br = "Nenhum dos dois espaços de save está intacto - o jogo diria que este save está corrompido", pt = "Nenhum dos dois espaços está intacto - o jogo diria que esta gravação está corrompida", zh = "两个存档槽位都不完整，游戏会将此存档视为损坏"),
    "The save's sectors disagree on its save counter" to Tr(ja = "セーブの セクターの カウンターが あいません", fr = "Les secteurs de la sauvegarde n'ont pas le même compteur", de = "Die Sektoren des Spielstands haben verschiedene Zähler", it = "I settori del salvataggio non hanno lo stesso contatore", es = "Los sectores de la partida no tienen el mismo contador", br = "Os setores do save não concordam no contador de saves", pt = "Os setores da gravação não concordam no contador", zh = "存档各区块的保存计数不一致"),
    "Tap where it goes - any box" to Tr(ja = "おく ばしょを タッチ (どの ボックスでも)", fr = "Touchez où le mettre (n'importe quelle boîte)", de = "Tippe, wohin es soll (jede Box)", it = "Tocca dove metterlo (qualsiasi box)", es = "Toca dónde ponerlo (cualquier caja)", br = "Toque onde colocar - qualquer caixa", pt = "Toque onde colocar - qualquer caixa", zh = "点按目标位置，可选择任意盒子"),
    "Not saved yet" to Tr(ja = "まだ セーブしていません", fr = "Pas encore sauvegardé", de = "Noch nicht gespeichert", it = "Non ancora salvato", es = "Aún sin guardar", br = "Ainda não salvo", pt = "Ainda não guardado", zh = "尚未保存"),
    "UNDO ALL" to Tr(ja = "ぜんぶ もどす", fr = "TOUT ANNULER", de = "ALLES ZURÜCK", it = "ANNULLA TUTTO", es = "DESHACER TODO", br = "DESFAZER TUDO", pt = "DESFAZER TUDO", zh = "全部撤销"),
    "SAVE CHANGES?" to Tr(ja = "セーブ しますか?", fr = "SAUVER LES CHANGEMENTS ?", de = "ÄNDERUNGEN SICHERN?", it = "SALVARE LE MODIFICHE?", es = "¿GUARDAR LOS CAMBIOS?", br = "SALVAR AS MUDANÇAS?", pt = "GUARDAR AS ALTERAÇÕES?", zh = "保存更改？"),
    "Written the way the game saves: the save as it is now stays in the file as the game's fallback, and a copy goes to pokedaisy-backups. The game starts from the save next time, not from a resume state." to Tr(ja = "ゲームと おなじ やりかたで かきこみます: いまの セーブは ファイルの なかに ゲームの よびとして のこり、 コピーが pokedaisy-backups に はいります。 つぎは つづきの ステートでなく セーブから はじまります。", fr = "Écrit comme le jeu sauvegarde : la sauvegarde actuelle reste dans le fichier comme secours du jeu, et une copie va dans pokedaisy-backups. Le jeu repartira de la sauvegarde, pas d'un état de reprise.", de = "So geschrieben, wie das Spiel speichert: Der jetzige Spielstand bleibt als Rückfall des Spiels in der Datei, eine Kopie kommt nach pokedaisy-backups. Das Spiel startet nächstes Mal vom Spielstand, nicht von einem Fortsetzungsstand.", it = "Scritto come salva il gioco: il salvataggio attuale resta nel file come riserva del gioco e una copia va in pokedaisy-backups. Il gioco ripartirà dal salvataggio, non da uno stato di ripresa.", es = "Se escribe como guarda el juego: la partida actual queda en el archivo como respaldo del juego y una copia va a pokedaisy-backups. El juego empezará desde la partida, no desde un estado de reanudación.", br = "Gravado do jeito que o jogo salva: o save atual fica no arquivo como reserva do jogo, e uma cópia vai para pokedaisy-backups. Na próxima vez o jogo começa do save, não de um estado de retomada.", pt = "Escrito como o jogo guarda: a gravação atual fica no ficheiro como reserva do jogo, e uma cópia vai para pokedaisy-backups. Da próxima vez, o jogo começa da gravação, não de um estado de retoma.", zh = "按游戏的保存方式写入：当前存档保留在文件中作为备用，并复制一份到 pokedaisy-backups。下次游戏将从存档开始，而不是从恢复状态继续。"),
    "DISCARD CHANGES?" to Tr(ja = "かえた ことを すてますか?", fr = "ABANDONNER LES CHANGEMENTS ?", de = "ÄNDERUNGEN VERWERFEN?", it = "SCARTARE LE MODIFICHE?", es = "¿DESCARTAR LOS CAMBIOS?", br = "DESCARTAR AS MUDANÇAS?", pt = "DESCARTAR AS ALTERAÇÕES?", zh = "放弃更改？"),
