    "ADD MOVE" to Tr(ja = "わざを ふやす", fr = "AJOUTER UNE CAPACITÉ", de = "ATTACKE HINZUFÜGEN", it = "AGGIUNGI MOSSA", es = "AÑADIR MOVIMIENTO", br = "ADICIONAR GOLPE", pt = "ADICIONAR GOLPE", zh = "添加招式"),
