    "Key items and HMs stay as the game gave them" to Tr(ja = "だいじな ものと ひでんマシンは ゲームが くれた ままです", fr = "Objets rares et CS restent tels que le jeu les a donnés", de = "Basis-Items und VM bleiben, wie das Spiel sie gab", it = "Strumenti base e MN restano come li ha dati il gioco", es = "Los objetos clave y las MO se quedan como los dio el juego", br = "Itens-chave e MOs ficam como o jogo os deu", pt = "Itens-chave e MOs ficam como o jogo os deu", zh = "重要物品和秘传学习器保留游戏中的原有内容"),
    // TRADE (two saves' PC boxes)
    "No other game here has a save PC BOXES can read" to Tr(ja = "パソコンの ボックスで よめる セーブの ゲームが ほかに ありません", fr = "Aucun autre jeu ici n'a une sauvegarde lisible par BOÎTES PC", de = "Kein anderes Spiel hier hat einen Spielstand, den PC-BOXEN lesen kann", it = "Nessun altro gioco qui ha un salvataggio leggibile da BOX PC", es = "Ningún otro juego aquí tiene una partida que CAJAS PC pueda leer", br = "Nenhum outro jogo aqui tem um save que CAIXAS DO PC consiga ler", pt = "Nenhum outro jogo aqui tem uma gravação que CAIXAS DO PC consiga ler", zh = "这里没有其他游戏的存档可供电脑盒子读取"),
    "TRADE WITH" to Tr(ja = "こうかんする あいて", fr = "ÉCHANGER AVEC", de = "TAUSCHEN MIT", it = "SCAMBIA CON", es = "INTERCAMBIAR CON", br = "TROCAR COM", pt = "TROCAR COM", zh = "交换对象"),
    "Both games use the same save file" to Tr(ja = "ふたつの ゲームが おなじ セーブを つかっています", fr = "Les deux jeux utilisent la même sauvegarde", de = "Beide Spiele nutzen denselben Spielstand", it = "I due giochi usano lo stesso salvataggio", es = "Los dos juegos usan la misma partida", br = "Os dois jogos usam o mesmo arquivo de save", pt = "Os dois jogos usam o mesmo ficheiro de gravação", zh = "两款游戏使用同一个存档文件"),
    "A Bad Egg can't be traded" to Tr(ja = "ダメタマゴは こうかん できません", fr = "Un Mauvais Œuf ne s'échange pas", de = "Ein schlechtes Ei kann nicht getauscht werden", it = "Un Uovo Guasto non si può scambiare", es = "Un Huevo Malo no se puede intercambiar", br = "Um Ovo Ruim não pode ser trocado", pt = "Um Ovo Mau não pode ser trocado", zh = "坏蛋无法交换"),
    "{0} has no National Dex yet, so no eggs" to Tr(ja = "{0}は まだ ぜんこくずかんが ないので タマゴは だめです", fr = "{0} n'a pas encore le Pokédex National : pas d'œufs", de = "{0} hat noch keinen Nationalen Pokédex: keine Eier", it = "{0} non ha ancora il Pokédex Nazionale: niente uova", es = "{0} aún no tiene la Pokédex Nacional: sin huevos", br = "{0} ainda não tem a Pokédex Nacional, então nada de ovos", pt = "{0} ainda não tem a Pokédex Nacional, por isso nada de ovos", zh = "{0}尚未获得全国图鉴，无法交换蛋"),
    "{0} has no National Dex yet, so no {1}" to Tr(ja = "{0}は まだ ぜんこくずかんが ないので {1}は だめです", fr = "{0} n'a pas encore le Pokédex National : pas de {1}", de = "{0} hat noch keinen Nationalen Pokédex: kein {1}", it = "{0} non ha ancora il Pokédex Nazionale: niente {1}", es = "{0} aún no tiene la Pokédex Nacional: sin {1}", br = "{0} ainda não tem a Pokédex Nacional, então nada de {1}", pt = "{0} ainda não tem a Pokédex Nacional, por isso nada de {1}", zh = "{0}尚未获得全国图鉴，无法交换{1}"),
    "This {0} isn't from an event, so the games won't trade it" to Tr(ja = "この {0}は イベントの ポケモンでは ないので こうかん できません", fr = "Ce {0} ne vient pas d'un événement : les jeux ne l'échangent pas", de = "Dieses {0} stammt nicht von einem Event: die Spiele tauschen es nicht", it = "Questo {0} non viene da un evento: i giochi non lo scambiano", es = "Este {0} no viene de un evento: los juegos no lo intercambian", br = "Este {0} não é de um evento, então os jogos não o trocam", pt = "Este {0} não é de um evento, por isso os jogos não o trocam", zh = "这只{0}不是活动获得的，游戏不允许交换"),
    "Mail and Enigma Berries stay with their save: take it off in the game first" to Tr(ja = "メールと ナゾのみは セーブに のこります。 さきに ゲームで はずしてください", fr = "Lettres et Baies Énigma restent avec leur sauvegarde : retirez-les d'abord dans le jeu", de = "Briefe und Enigmabeeren bleiben bei ihrem Spielstand: nimm sie zuerst im Spiel ab", it = "Lettere e Baccaenigma restano nel loro salvataggio: toglile prima nel gioco", es = "Las cartas y las Bayas Enigma se quedan en su partida: quítalas antes en el juego", br = "Cartas e Frutas Enigma ficam no seu save: tire-as no jogo primeiro", pt = "Cartas e Frutas Enigma ficam na sua gravação: retire-as primeiro no jogo", zh = "邮件和谜芝果必须留在原存档中，请先在游戏中取下"),
    "{0} links with Ruby, Sapphire and Emerald only after the Sevii Islands" to Tr(ja = "{0}は ナナシマの あとでないと ルビー・サファイア・エメラルドと つなげません", fr = "{0} ne se connecte à Rubis, Saphir et Émeraude qu'après les Îles Sevii", de = "{0} verbindet sich erst nach den Sevii Eilanden mit Rubin, Saphir und Smaragd", it = "{0} si collega a Rubino, Zaffiro e Smeraldo solo dopo le Isole Settipelago", es = "{0} solo conecta con Rubí, Zafiro y Esmeralda tras las Islas Sete", br = "{0} só se conecta com Ruby, Sapphire e Emerald depois das Ilhas Sevii", pt = "{0} só se liga a Ruby, Sapphire e Emerald depois das Ilhas Sevii", zh = "{0}只有在完成七之岛相关进度后才能与红宝石、蓝宝石和绿宝石连接"),
    "There's no Pokémon there" to Tr(ja = "そこに ポケモンは いません", fr = "Il n'y a pas de Pokémon ici", de = "Dort ist kein Pokémon", it = "Lì non c'è nessun Pokémon", es = "Ahí no hay ningún Pokémon", br = "Não há nenhum Pokémon aí", pt = "Não há nenhum Pokémon aí", zh = "这里没有宝可梦"),
    "That slot isn't empty" to Tr(ja = "その ばしょは あいていません", fr = "Cet emplacement n'est pas vide", de = "Dieser Platz ist nicht frei", it = "Quel posto non è vuoto", es = "Ese hueco no está vacío", br = "Esse espaço não está vazio", pt = "Esse espaço não está vazio", zh = "该槽位不是空的"),
    "{0} goes to {1}" to Tr(ja = "{0}が {1}へ いきます", fr = "{0} part vers {1}", de = "{0} geht nach {1}", it = "{0} va in {1}", es = "{0} va a {1}", br = "{0} vai para {1}", pt = "{0} vai para {1}", zh = "{0}前往{1}"),
