    "Pick a slot on each side: a Pokémon for a Pokémon, or one for an empty slot" to Tr(ja = "りょうほうで ばしょを えらんでください: ポケモンと ポケモン、 または ポケモンと あいている ばしょ", fr = "Choisissez un emplacement de chaque côté : un Pokémon contre un Pokémon, ou vers un emplacement vide", de = "Wähle auf jeder Seite einen Platz: Pokémon gegen Pokémon, oder eines auf einen freien Platz", it = "Scegli un posto per lato: un Pokémon per un Pokémon, o uno verso un posto vuoto", es = "Elige un hueco en cada lado: un Pokémon por otro, o uno a un hueco vacío", br = "Escolha um espaço de cada lado: um Pokémon por outro, ou um para um espaço vazio", pt = "Escolha um espaço de cada lado: um Pokémon por outro, ou um para um espaço vazio", zh = "请在两侧各选择一个槽位：可以交换两只宝可梦，或将一只宝可梦移入空槽位"),
    "SEND" to Tr(ja = "おくる", fr = "ENVOYER", de = "SENDEN", it = "INVIA", es = "ENVIAR", br = "ENVIAR", pt = "ENVIAR", zh = "发送"),
    "SAVE BOTH?" to Tr(ja = "りょうほう セーブ しますか?", fr = "SAUVER LES DEUX ?", de = "BEIDE SICHERN?", it = "SALVARE ENTRAMBI?", es = "¿GUARDAR AMBAS?", br = "SALVAR OS DOIS?", pt = "GUARDAR AS DUAS?", zh = "保存两个存档？"),
    "Both saves are written the way the game saves, each backed up to pokedaisy-backups first. If the second can't be written, the first is put back, so no Pokémon is lost or copied." to Tr(ja = "ふたつの セーブを ゲームと おなじ やりかたで かきこみます。 さきに それぞれを pokedaisy-backups に コピーします。 ふたつめが かけなければ ひとつめを もどすので、 ポケモンが きえたり ふえたり しません。", fr = "Les deux sauvegardes sont écrites comme le jeu sauvegarde, chacune copiée d'abord dans pokedaisy-backups. Si la seconde échoue, la première est remise : aucun Pokémon n'est perdu ni copié.", de = "Beide Spielstände werden geschrieben, wie das Spiel speichert, jeder zuerst nach pokedaisy-backups kopiert. Klappt der zweite nicht, kommt der erste zurück: kein Pokémon geht verloren oder wird verdoppelt.", it = "Entrambi i salvataggi sono scritti come salva il gioco, ognuno copiato prima in pokedaisy-backups. Se il secondo non si scrive, il primo viene rimesso: nessun Pokémon perso o copiato.", es = "Las dos partidas se escriben como guarda el juego, cada una copiada antes en pokedaisy-backups. Si la segunda falla, la primera se repone: ningún Pokémon se pierde ni se duplica.", br = "Os dois saves são gravados do jeito que o jogo salva, cada um com backup em pokedaisy-backups antes. Se o segundo não puder ser gravado, o primeiro é restaurado, então nenhum Pokémon se perde ou é copiado.", pt = "As duas gravações são escritas como o jogo guarda, cada uma com cópia de segurança em pokedaisy-backups antes. Se a segunda não puder ser escrita, a primeira é reposta, por isso nenhum Pokémon se perde nem é copiado.", zh = "两个存档都会按游戏的保存方式写入，并先分别备份到 pokedaisy-backups。如果第二个存档写入失败，第一个会恢复原状，避免宝可梦丢失或重复。"),
    "The trades you made aren't saved. Leave without saving them?" to Tr(ja = "こうかんは セーブ していません。 セーブせずに もどりますか?", fr = "Les échanges ne sont pas sauvegardés. Quitter sans les sauver ?", de = "Die Tausche sind nicht gespeichert. Ohne Speichern verlassen?", it = "Gli scambi non sono salvati. Uscire senza salvarli?", es = "Los intercambios no están guardados. ¿Salir sin guardarlos?", br = "As trocas que você fez não foram salvas. Sair sem salvar?", pt = "As trocas que fez não foram guardadas. Sair sem guardar?", zh = "交换尚未保存，确定不保存就离开吗？"),
    "EVOLVING!" to Tr(ja = "しんか!", fr = "ÉVOLUTION !", de = "ENTWICKLUNG!", it = "EVOLUZIONE!", es = "¡EVOLUCIÓN!", br = "EVOLUINDO!", pt = "A EVOLUIR!", zh = "正在进化！"),
    "{0} evolves into {1} when it arrives." to Tr(ja = "{0}は とどくと {1}に しんかします。", fr = "{0} évolue en {1} à son arrivée.", de = "{0} entwickelt sich bei Ankunft zu {1}.", it = "{0} si evolve in {1} all'arrivo.", es = "{0} evoluciona a {1} al llegar.", br = "{0} evolui para {1} ao chegar.", pt = "{0} evolui para {1} ao chegar.", zh = "{0}到达后会进化成{1}。"),
    "DON'T EVOLVE" to Tr(ja = "しんか させない", fr = "PAS D'ÉVOLUTION", de = "NICHT ENTWICKELN", it = "NON EVOLVERE", es = "NO EVOLUCIONAR", br = "NÃO EVOLUIR", pt = "NÃO EVOLUIR", zh = "不要进化"),
)
